    for (var s3 = 0; s3 < 110; s3++) { var Ds = 4700; lamp(m, ctx, V.p((-1.1 + ctx.rnd() * 1.62) * Ds, YD - 30 + ctx.rnd() * 30, Ds), sz(Ds, 1.2), ctx.rnd() < 0.5 ? cc : cb, 0.2 + 0.35 * ctx.rnd()); }
    stars(m, ctx, V, 160, 0.02, 0.33, null, 0.6);
